export function ChecksTable({ results }: { results: CheckResult[] }) {
  return (
    <section className="panel">
      <h2>Engineering checks</h2>
      {results.length === 0 ? (
        <p className="muted">No verified candidates yet.</p>
      ) : (
        <table>
          <thead>
            <tr>
