              <th>Verdict</th>
              <th>Fit</th>
              {results[0].rows.map((r) => (
                <th key={r.check}>{r.check}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {results.map((res) => (
              <tr key={res.candidate}>
                <td>{res.candidate}</td>
                <td>{res.verdict === 'pass' ? 'Pass*' : res.verdict}</td>
                <td>{res.fit}</td>
                {res.rows.map((r) => (
